        "content": "नेपालको आधिकारिक राष्ट्रिय क्यालेन्डर **विक्रम संवत् (Bikram Sambat - BS)** सूर्यसिद्धान्तमा आधारित सौर-चान्द्र (Luni-Solar) गणना प्रणाली हो। यसमा वर्षको निर्धारण सूर्यको राशि परिवर्तन (संक्रान्ति) अनुसार सौर महिना (बैशाखदेखि चैत) का रूपमा गरिन्छ भने धार्मिक चाडपर्व, व्रत, उत्सव र संस्कार कर्महरू चन्द्रमाको गति अनुसार तिथि (शुक्ल पक्ष र कृष्ण पक्ष) का आधारमा तय गरिन्छ।\n\nविक्रम संवत् ईस्वी संवत् (AD) भन्दा **५६ वर्ष ८ महिना** जेठो छ। नेपालमा दैनिक सरकारी कामकाज, कानुनी लिखत, बैंकिङ कारोबार, नापी तथा मालपोतका काम र धार्मिक अनुष्ठान सम्पूर्ण रूपमा विक्रम संवतमै सम्पन्न हुन्छन्। \n\nआधुनिक प्रविधिको विकाससँगै मोबाइल फोनमा पात्रो हेर्ने बानी बढेको छ। हाम्रो **[बी.आर. पात्रो (BR Patro)](/patro)** मा नेपालका ७५३ वटै स्थानीय तहको अक्षांश र देशान्तर अनुसार शुद्ध स्थानीय सूर्योदय, सूर्यास्त, तिथि, नक्षत्र, योग, करण र विवाह/व्रतबन्धका साइतहरू एकीकृत गरिएको छ।",
