        "content": "तपाईंले कुनै पनि बाहिरी एप डाउनलोड नगरी सिधै आफ्नो मोबाइल वा कम्प्युटरको ब्राउजरबाट **[बी.आर. पात्रो (BR Patro)](/patro)** पूर्ण रूपमा चलाउन सक्नुहुन्छ:\n\n- **महिना अनुसार क्यालेन्डर हेर्ने**: वैशाखदेखि चैतसम्मका २०८१, २०८२, २०८३ र २०८४ का सम्पूर्ण महिनाहरू अघि-पछि गर्न सकिन्छ।\n- **दैनिक विस्तृत पञ्चाङ्ग**: कुनै पनि गतेमा क्लिक गर्नासाथ आजको सूर्योदय, सूर्यास्त, तिथि, नक्षत्र, योग, करण, राहुकाल र दिशाशूल विवरण खुल्नेछ।\n- **तिथि तथा मिति कन्भर्टर**: वि.सं. बाट ई.सं. (BS to AD) र ई.सं. बाट वि.सं. (AD to BS) सेकेन्डमै रूपान्तरण गर्न सकिन्छ।\n- **अफलाइन एन्ड्रोइड एप**: यदि तपाईं मोबाइलमा इन्टरनेट बिना नै दैनिक पञ्चाङ्ग र कुण्डली चलाउन चाहनुहुन्छ भने सोही पृष्ठबाट **आधिकारिक APK (v7.9.74)** डाउनलोड गर्न सक्नुहुन्छ।"
