        "content": "नेपालमा दर्ता स्रेस्ता कायम रहेको जग्गाको वास्तविक जग्गाधनी (लालपुर्जा बाहक) को मृत्यु भएपछि निजको नाममा रहेको अचल सम्पत्ति कानुनी हकवाला (Successors / Legal Heirs) को नाममा आधिकारिक रूपमा सार्ने प्रक्रियालाई **\"जग्गा नामसारी\" (Land Succession / Transfer of Ownership)** भनिन्छ। मालपोत कार्यालयको भाषामा यसलाई **\"दाखिल खारेज\" (Dakhil Kharej)** भनिन्छ—अर्थात् मृतकको नाम लगतबाट खारेज गरी नयाँ हकवालाहरूको नाम दाखिल गर्ने।\n\nधेरै परिवारमा जग्गाधनीको मृत्युपछि पनि वर्षौंसम्म नामसारी नगरी मृतककै नाममा जग्गा छाड्ने गरिन्छ। तर समयमै नामसारी नगर्दा निम्न गम्भीर कानुनी समस्याहरू आउँछन्:\n1. **जग्गा बेचबिखन, बैना वा अंशबन्डा गर्न नमिल्ने**: मृतकको नाममा रहेको जग्गा कसैले किन्न सक्दैन।\n2. **बैंक कर्जा (Loan) नपाउने**: बैंकले मृतकको नामको लालपुर्जा धितो स्वीकार गर्दैन।\n3. **हकवालाहरू थपिँदै जाने वा मृत्यु हुने**: समय बित्दै जाँदा हकवालाहरूको पनि मृत्यु भई नाता प्रमाणित गर्न कठिन हुने र विवाद अदालत पुग्ने खतरा रहन्छ।\n4. **स्थानीय कर र सिफारिस रोकिने**: वडा कार्यालयले घरबाटो सिफारिस वा चारकिल्ला प्रमाणित दिन अस्वीकार गर्न सक्छ।",
