        "content": "नेपाल सरकारले जग्गाको खण्डीकरण रोक्न र व्यवस्थित सहरीकरण गर्न भू-उपयोग ऐन २०७६ र भू-उपयोग नियमावली २०७९ लागू गरेको थियो। तर स्थानीय तहहरूले समयमै जग्गा वर्गीकरण गर्न नसक्दा लामो समयसम्म देशभर कित्ताकाट ठप्प भई नागरिकहरू मर्कामा परेका थिए। \n\nयस समस्यालाई समाधान गर्न मन्त्रिपरिषद्ले **भू-उपयोग (दोस्रो संशोधन) नियमावली २०८१** जारी गर्दै कित्ताकाटलाई सहज बनाएको छ। नयाँ व्यवस्था अनुसार:\n- स्थानीय तहले आफ्नो पालिकाभित्रको जग्गालाई कम्तीमा **कृषि क्षेत्र (Agricultural Area)** र **गैर-कृषि/आवासीय क्षेत्र (Residential/Non-agricultural Area)** मा वर्गीकरण गरेपछि सोही अनुसार कित्ताकाट खुल्छ।\n- वर्गीकरण नभएको पालिकामा पनि स्थानीय भू-उपयोग परिषद्को निर्णय र सिफारिसका आधारमा कित्ताकाट गर्न सकिने खुकुलो प्रावधान राखिएको छ।",
