        "content": "क्षेत्रफल पुगेर मात्र कित्ताकाट हुँदैन; नयाँ बन्ने प्रत्येक कित्तामा सार्वजनिक बाटो जोडिएको हुनुपर्छ:\n\n1. **न्यूनतम बाटोको चौडाइ**:\n   - नयाँ प्लटिङ वा कित्ताकाट गर्दा आवासीय क्षेत्रमा न्यूनतम **६ मिटर देखि ८ मिटर (२० देखि २६ फिट)** चौडाइको बाटो हुनुपर्छ।\n   - पहिले नै बनेको बस्तीमा भने न्यूनतम ४ मिटर (१३ फिट) को बाटो अनिवार्य मानिन्छ।\n2. **न्यूनतम मोहडा (Frontage)**:\n   - बाटोतर्फ जोडिएको जग्गाको मुख (Frontage) कम्तीमा **८ मिटर (करिब २६ फिट)** हुनुपर्छ ताकि घर बनाउँदा दुवैतर्फ झ्याल र सेतब्याक छोड्न सकियोस्।\n3. **सार्वजनिक निकास (Dead End Road)**:\n   - यदि बाटो अगाडि गएर टुङ्गिन्छ (Dead End) भने सवारी साधन घुमाउनका लागि अन्तिममा न्यूनतम १० मिटर व्यासको 'टी' वा 'सर्कल' आकारको खाली ठाउँ छोड्नुपर्छ।\n\nजग्गाको आकार नाप्न र रेखाचित्र कोर्न हाम्रो **[जग्गा रेखाचित्र स्केचर (Plot Visualizer)](/tools/plot-visualizer)** प्रयोग गर्न सकिन्छ।"
