        "content": "यदि तपाईंको जग्गा रहेको पालिकामा अझै वर्गीकरण भएको छैन भने व्यक्तिगत रूपमा वर्गीकरण गराउने तरिका:\n\n- **निवेदन पेस**: सम्बन्धित वडा कार्यालयमा जग्गाको लालपुर्जा, नक्सा ट्रेस, तिरो रसिद सहित \"मेरो जग्गा आवासीय क्षेत्रमा वर्गीकरण गरिपाऊँ\" भनी निवेदन दिने।\n- **प्राविधिक निरीक्षण**: वडाको प्राविधिक/इन्जिनियरले फिल्डमा गएर वरिपरि बस्ती, बिजुली, पानी र बाटोको सुविधा भएको प्रतिवेदन तयार गर्छ।\n- **वडा सिफारिस**: वडा समितिले निर्णय गरी नगरपालिकाको \"स्थानीय भू-उपयोग परिषद्\" मा सिफारिस पठाउँछ।\n- **परिषद्को निर्णय**: नगरप्रमुख (मेयर) को अध्यक्षतामा बस्ने भू-उपयोग परिषद्ले जग्गालाई 'आवासीय' प्रमाणित गरी नापी र मालपोत कार्यालयलाई कित्ताकाट अनुमति पत्र पठाउँछ।"
