        "content": "सनातन वैदिक परम्परामा विवाह केवल दुई व्यक्तिको मिलन मात्र नभई दुई परिवार, संस्कार, र मानसिक-शारीरिक प्रकृतिको पवित्र आध्यात्मिक बन्धन मानिन्छ। विवाहपछि पति र पत्नी बीचको मानसिक तालमेल, स्वास्थ्य, वंश वृद्धि, आर्थिक समृद्धि र दीर्घायु कस्तो रहला भनी परीक्षण गर्न महर्षि पराशरले **\"अष्टकूट गुण मिलान\" (Ashtakoot Milan)** को सिद्धान्त प्रतिपादन गरेका थिए।\n\nयसमा वर र कन्याको जन्म नक्षत्र (Nakshatra) र चन्द्र राशि (Moon Sign) का आधारमा ८ वटा फरक-फरक दृष्टिकोणबाट कुल **३६ अङ्क (गुण)** को विश्लेषण गरिन्छ। ३६ गुण मिलानले जोडीको:\n- **मानसिक अनुकूलता (Mental Compatibility)**\n- **शारीरिक तथा जैविक स्वास्थ्य (Genetic & Biological Harmony)**\n- **सन्तान सुख र भाग्य वृद्धि (Childbirth & Prosperity)**\nसम्बन्धी सूक्ष्म वैज्ञानिक मार्गदर्शन प्रदान गर्छ।",
