        content: `नेपालमा घर वा जग्गा खरिदबिक्री गर्दा क्रेता (किन्ने व्यक्ति) र बिक्रेता (बेच्ने व्यक्ति) बीच अन्तिम मालपोत रजिस्ट्रेसन पास हुनुपूर्व आपसी प्रतिबद्धता स्वरूप दिइने पेश्की रकमलाई **"बैना" (Earnest Money / Bayana)** भनिन्छ। बैना कारोबारलाई औपचारिक रूप दिन दुवै पक्ष, साक्षीहरू र लेखापढी/कानुन व्यवसायी बसेर तयार पारिने लिखित सम्झौतालाई **"बैनापट्टा" (Earnest Money Agreement)** भनिन्छ।

बैना गर्नुको मुख्य उद्देश्य जग्गाधनीले सो जग्गा अन्य कसैलाई बिक्री नगरोस् र क्रेताले पनि निश्चित समयभित्र बाँकी रकम जुटाएर जग्गा पास गरोस् भन्ने सुनिश्चितता गर्नु हो। तर पछिल्लो समय बैना कागजकै आधारमा करोडौँ रुपैयाँ फस्ने, दोहोरो बैना गरेर ठगी गर्ने र वर्षौंसम्म अदालत धाउनुपर्ने घटनाहरू दिनहुँ बढिरहेका छन्।`,
