        content: `जग्गा खरिद र विशेषगरी **बिक्री (Exit Strategy)** गर्दा तिर्नुपर्ने कर नै व्यक्तिगत र कम्पनी बीचको सबैभन्दा ठूलो आर्थिक भिन्नता हो:

### क) व्यक्तिगत नाममा जग्गा हुँदा (Individual CGT):
व्यक्तिले आफ्नो नामको जग्गा बिक्री गर्दा **आयकर ऐन, २०५८ को दफा ९५(क)** बमोजिम पुँजीगत लाभकर (Capital Gains Tax - CGT) लाग्दछ:
* **५ वर्षभन्दा बढी स्वामित्व (Holding Period > 5 Years):** कुल खुद नाफा (Profit) मा **५% (पाँच प्रतिशत)** मात्र लाभकर लाग्छ।
* **५ वर्षभन्दा कम स्वामित्व (Holding Period < 5 Years):** कुल खुद नाफामा **७.५% (सात दशमलव पाँच प्रतिशत)** लाभकर लाग्छ।
* यो लाभकर अन्तिम कर (Final Withholding Tax) हो, अर्थात् यो मालपोतमै तिरेपछि व्यक्तिले व्यक्तिगत आयकर विवरणमा फेरि थप कर तिर्नु पर्दैन।

### ख) प्राइभेट कम्पनीको नाममा जग्गा हुँदा (Corporate Income Tax):
कम्पनीले जग्गा बिक्री गर्दा हुने नाफालाई कम्पनीको नियमित **व्यावसायिक आम्दानी (Business Income)** मानिन्छ:
* कम्पनीको खुद नाफामा सामान्यतया **२५% (पच्चीस प्रतिशत)** कर्पोरेट आयकर लाग्छ।
* यद्यपि, उत्पादनमूलक वा विशेष सहुलियत प्राप्त उद्योगको हकमा यो दर २०% वा सोभन्दा कम पनि हुन सक्छ।
* यदि पहिलो नजरमा हेर्दा ५-७.५% भन्दा २५% धेरै देखिए तापनि कम्पनीले पाउन सक्ने **खर्च कट्टी (Expense Deductions)** ले वास्तविक कर निकै न्यून बनाइदिन्छ।`,
