            ['नोक्सानी सार्न पाउने (Loss Carry Forward)', 'अन्य सम्पत्तिसँग सजिलै मिल्दैन', 'आगामी ७ वर्षसम्मको नाफासँग नोक्सान मिलान गर्न पाइने']
