        content: 'निर्देशिकाको परिच्छेद १ मा नापी र जग्गा प्रशासनसँग जोडिएका आधारभूत प्राविधिक पदावलीहरूलाई स्पष्ट रूपमा परिभाषित गरिएको छ:\n\n• SOP (Standard Operating Procedure): नापी विभागबाट स्वीकृत नाप नक्सा सम्बन्धी मानक सञ्चालन कार्यविधि।\n• कित्ता (Parcel): कुनै एक व्यक्तिको हक, स्वामित्व र भोगभित्र रहेको, चारकिल्ला स्पष्ट छुट्टिएको र छुट्टै कित्ता नम्बर दिइएको जग्गाको अंश।\n• कित्ताकाट (Sub-division): प्रचलित कानुन बमोजिम कुनै कित्ता जग्गालाई दुई वा दुईभन्दा बढी कित्तामा विभाजन गर्ने कार्य।\n• कित्ता एकीकरण (Amalgamation): एउटै जग्गाधनीको स्वामित्व र भोगमा रहेका जोडिएका दुई वा बढी कित्ताहरूलाई मिलाएर एउटै कित्ता कायम गर्ने कार्य।\n• टायल चेक (Tile Check): नक्सामा रहेको कित्ताको क्षेत्रफल र स्रेस्ता (फिल्डबुक/लालपुर्जा) मा उल्लिखित क्षेत्रफलबीच प्राविधिक हिसाबले तुलना र परीक्षण गरी एकरूपता यकिन गर्ने कार्य।\n• छुट जग्गा (Unregistered/Omitted Land): साविक नापी हुँदा दर्ता प्रमाण भएर पनि नापी हुन छुट भएको वा नापी भई फिल्डबुकमा नाम उल्लेख भएको तर लालपुर्जा बन्न छुट भएको जग्गा।\n• फिल्ड रेखाङ्कन (Demarcation): नक्सा र स्रेस्ताका आधारमा जमिनको वास्तविक धरातलमा पुगी कित्ताको सिमाना र कुनाहरू यकिन गरी देखाइदिने कार्य।\n• पुनः नाप जाँच (Re-survey): साविक नाप नक्सा धरातलसँग नमिल्ने भएमा वा पुराना नक्सा नष्ट भएमा नयाँ प्रविधिबाट पुनः गरिने सम्पूर्ण नाप जाँच कार्य।'
