        content: 'परिच्छेद २, ३ र ४ (दफा ३ देखि ९) ले फिल्ड नाप जाँचका वैज्ञानिक विधिहरू निर्धारण गरेको छ:\n\n१. नियन्त्रण विन्दु (Control Points): राष्ट्रिय ग्रिड प्रणालीसँग आबद्ध हुने गरी पहिलो, दोस्रो, तेस्रो र चौथो तहका कन्ट्रोल पोइन्टहरू GNSS/DGPS प्रविधि प्रयोग गरी स्थापना गर्नुपर्नेछ (दफा ३-५)।\n२. आधुनिक नापी प्रणाली: अब नाप जाँच गर्दा परम्परागत प्लेन टेबलको सट्टा आधुनिक डिजिटल क्याडस्ट्रल (Digital Cadastral Survey), टोटल स्टेसन (Total Station) र जीआईएस विधिबाट नाप जाँच गरिनेछ।\n३. ७ दिने पूर्व सूचना (दफा ९): कुनै पनि क्षेत्रमा नाप जाँच सुरु गर्नुभन्दा कम्तीमा ७ दिन अगावै सम्बन्धित स्थानीय तह, वडा कार्यालय र सार्वजनिक स्थानहरूमा अनिवार्य सूचना टाँस गर्नुपर्नेछ।\n४. जग्गाधनीको दायित्व: सूचना प्रकाशित भएपछि आफ्नो जग्गाको सिमानामा स्वयं उपस्थित भई साँध-सिमाना देखाइदिनु जग्गाधनी तथा साँध-सँधियारको अनिवार्य दायित्व हुनेछ।\n५. २१ दिने सार्वजनिक सूचना (दफा ९(१३)): दर्ता प्रमाण नभएका तर परम्परागत भोग रहेका स्वबासी, बेनिस्सा वा गाउँब्लक क्षेत्रमा हकदाबी र विरोधका लागि २१ दिनको म्याद दिई सार्वजनिक सूचना प्रकाशन गर्नुपर्नेछ।'
