        content: 'जग्गा दर्ता गर्दा साविक नक्सा, फिल्डबुक र हालको वास्तविक भोग पूर्ण रूपमा भिडान हुनुपर्नेछ (दफा १०)। डिजिटल ट्रेस भिडान गर्दा कम्तीमा ३ वटा स्थायी नियन्त्रण विन्दु वा पहिचानयुक्त संरचना (Permanent Control Points / Identifiable Features) मिलेको हुनु अनिवार्य गरिएको छ।\n\nविवाद र संरक्षण सम्बन्धी प्रमुख व्यवस्थाहरू:\n• तेरो-मेरो विवाद (Disputed Land): दर्ताका क्रममा हक स्वामित्वमा विवाद भएमा सर्जमिन मुचुल्का गरी ३५ दिनभित्र अदालत जान म्याद दिइनेछ; अदालतमा मुद्दा चलेमा किनारा नलागेसम्म दर्ता रोक्का राखिनेछ।\n• ठाउँसरी भोग (दफा ११): साविक दर्ता भएको स्थानभन्दा फरक ठाउँमा भोग रहेको पाइएमा दुवै पक्षको लिखित सहमति, स्थानीय तहको सिफारिस र प्राविधिक जाँच बिना ठाउँसरी भोग दर्ता गर्न पूर्ण निषेध गरिएको छ।\n• एकल धर्को बाटो/कुलो (दफा १३): साविक नक्सामा एकल धर्को (Single Line) कोरिएको बाटो वा कुलो हाल धरातलमा प्रयोगमा रहेको भए सोही बमोजिम सरकारी/सार्वजनिक कायम गरिनेछ। यदि धरातलमा अस्तित्व नै नभएको र व्यक्तिको दर्ताभित्र परेको प्रमाणित भएमा स्थानीय तहको स्थलगत सिफारिस र सर्जमिन मुचुल्काका आधारमा मात्र निर्णय गरिनेछ।',
