        content: '• फिल्ड रेखाङ्कन (दफा ३७-४३): जग्गाधनीले तोकिएको सरकारी दस्तुर तिरी अनुसूची बमोजिम नापी कार्यालयमा निवेदन दिनुपर्नेछ। रेखाङ्कन हुने दिनभन्दा अगावै चारकिल्लाका साँध-सँधियारहरूलाई अनिवार्य जानकारी गराउनुपर्नेछ। अमिन/सर्भेयरले सिट नक्सा, कन्ट्रोल पोइन्ट र फिल्डबुकका आधारमा आधुनिक उपकरण (Total Station/GNSS वा फिता) प्रयोग गरी जमिनमा किला गाडेर सिमाना देखाइदिने र रोहबरमा मुचुल्का तयार गर्नेछन्।\n\n• नक्सा सुधार (दफा ४४-४७): साविक नापी वा कित्ताकाट गर्दा प्राविधिक कारणले नक्सामा गलत रेखा कोरिएको, मसी भर्दा त्रुटि भएको वा स्रेस्तामा क्षेत्रफल ठीक भएर नक्सामा आकार फरक परेको अवस्थामा मात्र नक्सा सुधार हुनेछ। मालपोत ऐन, २०३४ को दफा ८क को उपदफा (२) बमोजिम स्थलगत सर्जमिन मुचुल्का, सँधियारको सहमति र प्राविधिक विश्लेषण गरी नापी अधिकृतले निर्णय गर्नेछन्। नक्सा सुधार गर्दा सरकारी, सार्वजनिक वा सँधियारको जग्गा मिच्न पूर्ण प्रतिबन्ध छ।'
