        content: 'पहिले मालपोत कार्यालयमै गएर पुस्तक पल्टाउनु पर्ने झन्झट थियो। तर अहिले भूमि व्यवस्था तथा अभिलेख विभाग (DOLIA) को पोर्टल र हाम्रो [मालपोत क्यालकुलेटर](/tools/malpot-calculator) प्रयोग गरेर घरमै बसेर दररेट पत्ता लगाउन सकिन्छ:\n\n१. **जिल्ला र मालपोत कार्यालय छान्नुहोस्**: आफ्नो जग्गा पर्ने मालपोत कार्यालय (जस्तै: कलङ्की, डिल्लीबजार, वा भरतपुर)।\n२. **स्थानीय तह र वडा नम्बर**: पालिकाको नाम र वडा चयन गर्नुहोस्।\n३. **सडक वा टोलको नाम**: तपाईंको जग्गा रहेको सडक वा टोलको नामावली खोज्नुहोस्।\n४. **बाटोको प्रकृति पत्ता लगाउनुहोस्**: तपाईंको जग्गा छुने बाटो पिच, ग्राभेल, ढलान वा गोरेटो के हो छान्नुहोस्।\n५. **थैली अंक गणना गर्नुहोस्**: जग्गाको कुल क्षेत्रफल (रोपनी-आना वा बिघा-कट्ठा) लाई प्रतिआना वा प्रतिकट्ठा दररेटले गुणन गर्नुहोस्।',
