        answer: 'सरकारी मूल्याङ्कन भनेको जिल्ला मूल्याङ्कन समितिले राजस्व असुलीका लागि तोकेको न्यूनतम वैधानिक दररेट हो। थैली अंक भनेको क्रेता र बिक्रेताबीच वास्तवमै जग्गा खरिदबिक्री भएको आपसी सहमति मूल्य हो। कानुनतः थैली अंक सरकारी न्यूनतम दररेटभन्दा कम राख्न पाइँदैन।',
