        content: `मुलुकी देवानी संहिता अनुसार घरसारमा गरिएको बैनाबट्टा कागजलाई सम्बन्धित वडा कार्यालयबाट प्रमाणित गराउनु कानुनी रूपमा सुरक्षित हुन्छ। बैना कागजमा जग्गाको कित्ता नम्बर, क्षेत्रफल, कुल मूल्य, बैना रकम, बाँकी रकम बुझाउने अन्तिम भाका र यदि कुनै पक्षले सर्त उल्लंघन गरेमा हुने क्षतिपूर्तिको व्यवस्था स्पष्ट खुलाउनुपर्छ।`,
