        content: `नेपालमा घरजग्गा कारोबारमा सामान्यतया १ देखि २ प्रतिशतसम्म सेवा शुल्क वा कमिसनको चलन छ। तर धेरैजसो बिचौलियाहरूले जग्गाधनीसँग एउटा मूल्य तय गरी ग्राहकसँग धेरै बढी मूल्य लिने (काटेर खाने) गर्छन्। त्यसैले खरिदकर्ता र बिक्रेता प्रत्यक्ष आमने-सामने बसेर मूल्य तय गर्नु र एजेन्टलाई खुला रूपमा तय गरिएको निश्चित प्रतिशत पारिश्रमिक दिनु सबैभन्दा सुरक्षित विधि हो।`,
