        content: `गुठी संस्थान ऐन २०३३ अनुसार नेपालमा गुठी जग्गाहरू मुख्यतया तीन प्रकारका हुन्छन्:
१. **गुठी रैतान नम्बरी:** यो जग्गा पूर्ण रूपमा रैकर जग्गा सरह हुन्छ। यसको किनबेच, धितो बन्धक र नामसारी सामान्य रैकर जग्गा जस्तै मालपोत कार्यालयबाटै सहजै हुन्छ।
२. **गुठी अधीनस्थ (कमी/तामेली):** यो जग्गा गुठीको स्वामित्वमा रहन्छ तर व्यक्तिले जोतभोग गर्ने अधिकार पाएको हुन्छ। यसको किनबेच गर्दा गुठी संस्थानको स्वीकृति चाहिन्छ।
३. **गुठी तैनाथी:** यो पूर्ण रूपमा गुठी संस्थानको प्रत्यक्ष रेखदेख र स्वामित्वमा रहने जग्गा हो। यस्तो जग्गा कसैको निजी नाममा दर्ता वा बिक्री गर्न पाइँदैन।`,
