        content: `काठमाडौँ उपत्यकामा जनघनत्व र जग्गा कारोबार बढी भएकाले विभिन्न क्षेत्रका लागि छुट्टाछुट्टै नापी र मालपोत कार्यालयहरू तोकिएका छन्:

१. **डिल्लीबजार कार्यालय (काठमाडौँ):**
   - **कार्यक्षेत्र:** काठमाडौँ महानगरपालिकाका पुराना र भित्री वडाहरू।
   - **विशेषता:** उपत्यकाकै सबैभन्दा पुरानो अभिलेखालय भएको कार्यालय।

२. **कलंकी कार्यालय:**
   - **कार्यक्षेत्र:** काठमाडौँ महानगरपालिकाका पश्चिम क्षेत्रका वडाहरू, चन्द्रागिरि नगरपालिका, नागार्जुन नगरपालिका र कीर्तिपुर नगरपालिका।
   - **सेवा:** कलंकी मालपोत र नापी कार्यालयले उपत्यकाको पश्चिम भेगको सम्पूर्ण जग्गा प्रशासन हेर्छ।

३. **मैतिदेवी / चाबहिल कार्यालय:**
   - **कार्यक्षेत्र:** काठमाडौँ महानगरपालिकाका पूर्व-उत्तर वडाहरू, बानेश्वर, चाबहिल, गोकर्णेश्वर, कागेश्वरी मनोहरा र शंखरापुर नगरपालिका।

४. **मनमैजु कार्यालय:**
   - **कार्यक्षेत्र:** तारकेश्वर नगरपालिका र टोखा नगरपालिका लगायतका उत्तरी क्षेत्र।

५. **ललितपुर तथा भक्तपुर कार्यालय:**
   - **ललितपुर:** लगनखेलस्थित नापी र मालपोत कार्यालय (ललितपुर महानगर, गोदावरी र महालक्ष्मी नगरपालिका)।
   - **भक्तपुर:** भक्तपुर दरबार क्षेत्र नजिक रहेको कार्यालय (भक्तपुर, सूर्यविनायक, मध्यपुर थिमी र चाँगुनारायण)।`,
