        content: `नेपालमा जग्गा खरिदबिक्री (पास) गर्दा, दृष्टिबन्धक राख्दा, वा धितो मूल्याङ्कन गर्दा सरकारले लिनुपर्ने राजस्व निर्धारण गर्न प्रत्येक जिल्लाको मालपोत कार्यालयले तोकेको न्यूनतम आधार दर नै 'सरकारी मूल्याङ्कन' (Minimum Government Valuation) हो। मालपोत कार्यालयले तोकेको यो दरभन्दा कम मूल्य देखाएर जग्गा पास गर्न पाइँदैन।`,
