        content: `मालपोत ऐन २०३४ अनुसार प्रत्येक जिल्लामा **प्रमुख जिल्ला अधिकारी (CDO)** को संयोजकत्वमा 'जग्गा न्यूनतम मूल्याङ्कन समिति' हुन्छ। यस समितिमा जिल्ला समन्वय अधिकारी, मालपोत अधिकृत, नापी अधिकृत, र स्थानीय उद्योग वाणिज्य संघका प्रतिनिधिहरू हुन्छन्। यो समितिले प्रत्येक वर्ष साउन १ गतेदेखि लागु हुने गरी नयाँ दर सार्वजनिक गर्छ।`,
