        content: 'नेपालमा जग्गा खरिद-बिक्री (मालपोत रजिष्ट्रेसन पास), बैंक तथा वित्तीय संस्थाबाट धितो कर्जा (Loan) निकाल्न वा घर बनाउन नगरपालिकामा नक्सा पास गर्न जाँदा सबैभन्दा पहिले मागिने कागजात घरबाटो प्रमाणित सिफारिस (Ghar Bato Sifaris) हो।\n\nसम्बन्धित स्थानीय तहको वडा कार्यालयले आफ्नो वडाभित्र रहेको कित्ता जग्गामा कुन स्तरको बाटो पुगेको छ र त्यसमा घर बनेको छ वा छैन भनी स्थलगत निरीक्षणपछि जारी गर्ने आधिकारिक प्रमाणपत्र नै घरबाटो सिफारिस हो।\n\nमालपोत कार्यालयले जग्गा पास गर्दा रजिष्ट्रेसन दस्तुर र थैली अंक (सरकारी मूल्याङ्कन) निर्धारण गर्ने मुख्य आधार नै वडाको घरबाटो सिफारिस हो। बाटोको प्रकार (कालोपत्रे, ग्राभेल, कच्ची वा गोरेटो) अनुसार सरकारी मूल्याङ्कन र राजस्व फरक-फरक हुने भएकाले मालपोत कार्यालयले वडाको सिफारिस बिना कुनै पनि जग्गा रजिष्ट्रेसन गर्दैन।',
