        content: 'प्रत्येक स्थानीय तहको नगरसभा वा गाउँसभाले पारित गरेको आर्थिक ऐन अनुसार घरबाटो सिफारिस दस्तुर तोकिएको हुन्छ। सामान्यतया नेपालभर प्रचलित औसत दरहरू यस प्रकार छन्:\n\n• काठमाडौँ महानगरपालिका: प्रति कित्ता रु. १,००० देखि रु. २,००० सम्म।\n• अन्य उपमहानगरपालिका तथा नगरपालिका: प्रति कित्ता रु. ५०० देखि रु. १,००० सम्म।\n• गाउँपालिका क्षेत्र: प्रति कित्ता रु. ३०० देखि रु. ५०० सम्म।\n• बैंक धितो कर्जा प्रयोजन: कुनै-कुनै पालिकाहरूले व्यावसायिक प्रयोजनका लागि थप रु. ५०० सम्म शुल्क लिन सक्छन्।'
